package com.brightloop.model;
import jakarta.persistence.*;import java.math.BigDecimal;import java.time.LocalDate;
@Entity @Table(uniqueConstraints=@UniqueConstraint(columnNames={"subscription_id","period_start"})) public class Invoice { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Column(nullable=false,unique=true) public String number; @ManyToOne(optional=false) public Subscription subscription; @ManyToOne(optional=false) public Customer customer; public LocalDate invoiceDate; public LocalDate dueDate; public BigDecimal subtotal=BigDecimal.ZERO; public BigDecimal tax=BigDecimal.ZERO; public BigDecimal discount=BigDecimal.ZERO; public BigDecimal total=BigDecimal.ZERO; public BigDecimal paidAmount=BigDecimal.ZERO; @Enumerated(EnumType.STRING) public Status status=Status.DRAFT; public String description; public LocalDate periodStart; public enum Status{DRAFT,CONFIRMED,PAID,CANCELLED} }
